// JivoChat Bot API sender — the OUTBOUND half (BOT_MESSAGE), used today only
// for the first-contact auto-acknowledgement, gated by JIVO_AUTOREPLY
// (default OFF — the owner switched our WhatsApp auto-greeting off the day
// before this shipped; nothing here replies by default).
//
// Endpoint shape (jivochat.com/help/api/bot-api.html):
//   POST https://bot.jivosite.com/webhooks/{provider_id}/{token}
// provider_id is issued by Jivo per bot integration (email them); the token
// is generated by US and pasted into the bot channel's settings — the same
// JIVO_WEBHOOK_TOKEN that authenticates inbound calls to our endpoint.
//
// Same contract as ../meta/whatsapp-cloud.ts's sender: config from env (null
// when unconfigured, never a throw), API failures return {ok:false}, every
// fetch bounded by AbortSignal.timeout.

import { randomUUID } from "node:crypto";

/** Bound on the Jivo call — house rule: every outbound fetch is capped. */
export const JIVO_SEND_TIMEOUT_MS = 10_000;

export interface JivoBotConfig {
  providerId: string;
  token: string;
  baseUrl: string;
}

/** Sender credentials from env; null (never a throw) when unconfigured. */
export function jivoBotConfigFromEnv(
  env: Record<string, string | undefined> = process.env
): JivoBotConfig | null {
  const providerId = env.JIVO_BOT_PROVIDER_ID?.trim();
  const token = env.JIVO_WEBHOOK_TOKEN?.trim();
  if (!providerId || !token) return null;
  return { providerId, token, baseUrl: "https://bot.jivosite.com" };
}

export interface JivoAutoReply {
  enabled: boolean;
  text: string;
}

const DEFAULT_AUTOREPLY_TEXT =
  "Thanks for your message! An agent will reply here shortly.";

/**
 * JIVO_AUTOREPLY: unset/anything but on|true|1 → OFF (default). The text is
 * JIVO_AUTOREPLY_TEXT or the house default.
 */
export function jivoAutoReplyFromEnv(
  env: Record<string, string | undefined> = process.env
): JivoAutoReply {
  const flag = env.JIVO_AUTOREPLY?.trim().toLowerCase();
  const enabled = flag === "on" || flag === "true" || flag === "1";
  return { enabled, text: env.JIVO_AUTOREPLY_TEXT?.trim() || DEFAULT_AUTOREPLY_TEXT };
}

export type JivoSendResult = { ok: true } | { ok: false; error: string; status?: number };

type FetchLike = typeof fetch;

/**
 * One TEXT BOT_MESSAGE into an open chat. clientId/chatId come from the
 * inbound event (bot CLIENT_MESSAGE carries both; webhooks events carry
 * chat_id + visitor.number as the client id).
 */
export async function sendBotText(
  cfg: JivoBotConfig,
  to: { clientId: string; chatId: string },
  text: string,
  fetchImpl: FetchLike = fetch
): Promise<JivoSendResult> {
  if (!to.clientId.trim() || !to.chatId.trim()) return { ok: false, error: "client_id and chat_id are required" };
  if (!text.trim()) return { ok: false, error: "empty text" };
  try {
    const res = await fetchImpl(`${cfg.baseUrl}/webhooks/${cfg.providerId}/${cfg.token}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        id: randomUUID(),
        client_id: to.clientId,
        chat_id: to.chatId,
        event: "BOT_MESSAGE",
        message: { type: "TEXT", text, timestamp: Math.floor(Date.now() / 1000) },
      }),
      signal: AbortSignal.timeout(JIVO_SEND_TIMEOUT_MS),
    });
    if (!res.ok) {
      const data = (await res.json().catch(() => null)) as { error?: { message?: unknown } } | null;
      const msg =
        typeof data?.error?.message === "string" ? data.error.message : `HTTP ${res.status}`;
      return { ok: false, error: msg.slice(0, 300), status: res.status };
    }
    return { ok: true };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}
